"""Modalidades independentes com enunciados e códigos inéditos; HTML/CSS anteriores preservados."""
SOURCE='Atividades autorais complementares • fundamentos trabalhados em aula'
def single_subjects():
    qs=[]
    def add(subject,id,activity,title,concept,code,options,answer,explanation,**extra):
        q=dict(subject=subject,id=id,curriculum=subject+'-v1',activity=activity,title=title,concept=concept,kind={'quiz':'Desafio de HTML' if subject=='html' else 'Desafio de CSS','classify':'Quem sou eu? 🔎','repair':'Conserte o HTML 🛠️' if subject=='html' else 'Conserte o CSS 🛠️','structure':'Monte o HTML 🧩','visual':'Duelo de estilos 🎨','selectors':'Caça aos seletores 🎯'}[activity],code=code,options=options,answer=answer,explanation=explanation,seconds=90,source=SOURCE,reflection_prompt='',position=sum(x['subject']==subject for x in qs),**extra)
